// 将素材表在画布中按格读取，并只清除与边缘相连的白底；保留白色衣物。
function extract(im,sx,sy,sw,sh){const c=document.createElement('canvas');c.width=Math.floor(sw);c.height=Math.floor(sh);const cctx=c.getContext('2d',{willReadFrequently:true});cctx.drawImage(im,sx,sy,sw,sh,0,0,c.width,c.height);const d=cctx.getImageData(0,0,c.width,c.height),p=d.data,w=c.width,h=c.height,N=w*h;const seen=new Uint8Array(N),queue=new Int32Array(N);let a=0,b=0;function light(n){const k=n*4;return p[k+3]<180||((Math.min(p[k],p[k+1],p[k+2])>219)&&(Math.max(p[k],p[k+1],p[k+2])-Math.min(p[k],p[k+1],p[k+2])<36))||(p[k]>200&&p[k+1]<65&&p[k+2]<90)||(p[k]>210&&p[k+1]>170&&p[k+2]<75)}function add(n){if(n>=0&&n<N&&!seen[n]&&light(n)){seen[n]=1;queue[b++]=n}}for(let x=0;x<w;x++){add(x);add((h-1)*w+x)}for(let y=0;y<h;y++){add(y*w);add(y*w+w-1)}while(a<b){const n=queue[a++],x=n%w;if(x)add(n-1);if(x<w-1)add(n+1);add(n-w);add(n+w)}for(let n=0;n<N;n++){if(seen[n]||p[n*4+3]<180)p[n*4+3]=0;seen[n]=0}let largest=[];for(let n=0;n<N;n++){if(seen[n]||p[n*4+3]===0)continue;a=0;b=0;queue[b++]=n;seen[n]=1;while(a<b){const k=queue[a++],x=k%w;for(const q of [x?k-1:-1,x<w-1?k+1:-1,k-w,k+w]){if(q>=0&&q<N&&!seen[q]&&p[q*4+3]>0){seen[q]=1;queue[b++]=q}}}if(b>largest.length)largest=Array.from(queue.subarray(0,b))}const keep=new Uint8Array(N);let x0=w,y0=h,x1=0,y1=0;for(const n of largest){keep[n]=1;const x=n%w,y=Math.floor(n/w);x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}for(let n=0;n<N;n++)if(!keep[n])p[n*4+3]=0;cctx.putImageData(d,0,0);const out=document.createElement('canvas');out.width=Math.max(1,x1-x0+1);out.height=Math.max(1,y1-y0+1);out.getContext('2d').drawImage(c,x0,y0,out.width,out.height,0,0,out.width,out.height);return out}
function makeSprites(){const im=assets.girlWalk;for(let row=0;row<4;row++)for(let col=0;col<5;col++)sprites['walk'+row+col]=extract(im,75+col*250,row*280,250,280);for(const n of ['girlActions','boy'])for(let r=0;r<4;r++)for(let c=0;c<4;c++)sprites[n+r+c]=extract(assets[n],c*assets[n].width/4,r*assets[n].height/4,assets[n].width/4,assets[n].height/4);const pc=$('#portrait').getContext('2d'),boy=sprites.boy00;pc.drawImage(boy,0,0,boy.width,boy.height*.58,7,4,76,96)}
let gardenCache=null;function homeBackground(){ctx.drawImage(assets.home,0,0,W,H);if(season>0){if(!gardenCache){gardenCache=document.createElement('canvas');gardenCache.width=W;gardenCache.height=H;const gc=gardenCache.getContext('2d');gc.filter=season===1?'hue-rotate(30deg) saturate(1.15)':season===2?'sepia(.55) saturate(1.7) hue-rotate(-20deg)':'saturate(.15) brightness(1.18)';gc.drawImage(assets.home,0,0,W,H)}ctx.save();ctx.beginPath();ctx.rect(0,0,165,H);ctx.rect(1515,0,W-1515,H);ctx.rect(0,0,W,38);ctx.rect(0,785,W,156);ctx.clip();ctx.drawImage(gardenCache,0,0);if(season===3){ctx.fillStyle='#eef4f0';ctx.globalAlpha=.36;ctx.fillRect(0,0,W,H)}ctx.restore()}}
let nightAmount=0;function drawLighting(dt){const target=phase==='night'?1:0;nightAmount+=(target-nightAmount)*Math.min(1,dt*.7);if(scene!=='home')return;if(nightAmount>.002){ctx.fillStyle=`rgba(20,34,66,${.48*nightAmount})`;ctx.fillRect(0,0,W,H);ctx.save();ctx.globalCompositeOperation='screen';for(const [x,y,r]of [[250,113,135],[706,435,145],[251,580,110],[825,790,115],[1370,810,100]]){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(255,207,112,${.37*nightAmount})`);g.addColorStop(1,'rgba(255,206,110,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}ctx.restore()}}
function spriteDraw(im,x,y,h,alpha=1){if(!im)return;ctx.save();ctx.globalAlpha=alpha;const w=h*im.width/im.height;ctx.drawImage(im,x-w/2,y-h,w,h);ctx.restore()}
function drawPlayer(now){if(pose){if(pose.type==='sleep'){const im=sprites.girlActions10;ctx.save();ctx.translate(pose.x,pose.y);ctx.rotate(Math.PI/2);const w=215,h=w*im.height/im.width;ctx.drawImage(im,-w/2,-h/2,w,h);ctx.restore();if(Math.floor(now/1200)%2===0){ctx.fillStyle='#929e8d';ctx.font='18px Georgia';ctx.fillText('z z',pose.x+65,pose.y-40)}}else if(pose.type==='sea')spriteDraw(sprites.walk14,pose.x,pose.y,102);else spriteDraw(sprites.girlActions03,pose.x,pose.y,107);return}const row={front:0,back:1,left:2,right:3}[player.dir];let col=player.moving?1+Math.floor(player.step/140)%3:0;spriteDraw(sprites['walk'+row+col],player.x,player.y,127)}
function drawNpc(now){const frame=Math.floor(now/6500)%5===0?'boy23':'boy00';spriteDraw(sprites[frame],npc.x,npc.y+Math.sin(now/1600)*1.5,129)}
function drawGift(){if(scene!=='home')return;const x=260,y=582;ctx.save();ctx.translate(x,y);ctx.lineJoin='round';ctx.fillStyle='#efd5b5';ctx.strokeStyle='#bc9074';ctx.lineWidth=2;ctx.fillRect(-19,-23,38,30);ctx.strokeRect(-19,-23,38,30);ctx.fillStyle='#f6e3c9';ctx.fillRect(-22,-29,44,9);ctx.strokeRect(-22,-29,44,9);ctx.fillStyle='#d3a091';ctx.fillRect(-3,-29,6,36);ctx.strokeStyle='#c78f84';ctx.beginPath();ctx.ellipse(-7,-34,8,4,.4,0,Math.PI*2);ctx.ellipse(7,-34,8,4,-.4,0,Math.PI*2);ctx.stroke();ctx.restore()}
function drawParticles(now){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;ctx.save();for(let i=0;i<22;i++){const speed=season===3?12:20;const x=((i*137.5+Math.sin(now/4000+i)*25+now*.004)%W+W)%W,y=(i*87+now*.001*speed)%(H+40)-20;if(scene==='home'&&x>160&&x<1510&&y>35&&y<795)continue;if(scene==='beach'&&y>850)continue;ctx.globalAlpha=season===3?.7:.45;ctx.fillStyle=['#f5b6b5','#f9e7a5','#c9954c','#ffffff'][season];ctx.beginPath();if(season===3)ctx.arc(x,y,2+(i%3),0,Math.PI*2);else ctx.ellipse(x,y,season===1?1.3:4,season===1?1.3:2.5,now/3000+i,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawDestination(now){if(!destination||now>destination.until||pose)return;const r=8+((now/250)%1)*8;ctx.strokeStyle='#fffbed';ctx.globalAlpha=.65;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(destination.x,destination.y,r,r*.5,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
function updateCamera(snap=false){const rect=stage.getBoundingClientRect(),ratio=rect.width/rect.height;let viewW=W/(zoomed?1.65:rect.width<600?1.42:1);let viewH=viewW/ratio;if(viewH>H){viewH=H;viewW=viewH*ratio}camera.w=viewW;camera.h=viewH;const x=Math.max(0,Math.min(W-viewW,(pose?pose.x:player.x)-viewW/2)),y=Math.max(0,Math.min(H-viewH,(pose?pose.y:player.y)-viewH/2));camera.x=snap?x:camera.x+(x-camera.x)*.075;camera.y=snap?y:camera.y+(y-camera.y)*.075}
function placeOverlays(now){for(const b of document.querySelectorAll('.hotspot')){const o=objects().find(o=>o.id===b.dataset.id),x=(o.x-camera.x)/camera.w*100,y=(o.y-camera.y)/camera.h*100;b.style.left=x+'%';b.style.top=y+'%';b.hidden=x<0||x>100||y<0||y>100;b.classList.toggle('near',Math.hypot(player.x-o.target[0],player.y-o.target[1])<110)}if(bubbleAt&&!$('#bubble').hidden){if(now>bubbleUntil)$('#bubble').hidden=true;const x=(bubbleAt.x-camera.x)/camera.w*100,y=(bubbleAt.y-camera.y)/camera.h*100;$('#bubble').style.left=Math.max(20,Math.min(80,x))+'%';$('#bubble').style.top=Math.max(24,Math.min(85,y))+'%'}}
function resize(){const r=stage.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);updateCamera(true)}
new ResizeObserver(resize).observe(stage);$('#zoom').onclick=()=>{zoomed=!zoomed;updateCamera(true);toast(zoomed?'拉近一点，看清小小的日常。':'看看整个小世界。')};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(stage.requestFullscreen)await stage.requestFullscreen();else{stage.classList.toggle('mobile-expanded');toast('可以横过手机，或用「调整视野」看清场景。')}}catch{toast('可以用「调整视野」拉近场景。')}};
function setDir(dx,dy){if(Math.abs(dx)>Math.abs(dy)*1.1)player.dir=dx>0?'right':'left';else if(Math.abs(dy)>.01)player.dir=dy>0?'front':'back'}
function tick(now){const dt=Math.min(1,(now-(lastFrame||now))/1000);lastFrame=now;if(ready){player.moving=false;if(!modal.open&&!switching){let dx=(keys.has('right')?1:0)-(keys.has('left')?1:0),dy=(keys.has('down')?1:0)-(keys.has('up')?1:0);if(dx||dy){standUp();route=[];pending=null;const norm=Math.hypot(dx,dy);dx/=norm;dy/=norm;const steps=Math.max(1,Math.ceil(215*dt/8)),speed=215*dt/steps;for(let n=0;n<steps;n++){if(walkable(player.x+dx*speed,player.y))player.x+=dx*speed;if(walkable(player.x,player.y+dy*speed))player.y+=dy*speed}setDir(dx,dy);player.moving=true}else if(route.length){let budget=240*dt;while(route.length&&budget>0){const dest=route[0],dx=dest.x-player.x,dy=dest.y-player.y,d=Math.hypot(dx,dy);setDir(dx,dy);if(d<=budget){player.x=dest.x;player.y=dest.y;route.shift();budget-=d}else{player.x+=dx/d*budget;player.y+=dy/d*budget;budget=0}}player.moving=true;if(!route.length&&pending){const a=pending;pending=null;perform(a)}}}if(player.moving)player.step+=dt*1000;updateCamera();ctx.setTransform(canvas.width/camera.w,0,0,canvas.height/camera.h,-camera.x*canvas.width/camera.w,-camera.y*canvas.height/camera.h);ctx.clearRect(camera.x,camera.y,camera.w,camera.h);if(scene==='home')homeBackground();else ctx.drawImage(assets[['spring','summer','autumn','winter'][season]+'-'+phase],0,0,W,H);drawGift();drawDestination(now);const py=pose?pose.y:player.y;if(py<npc.y){drawPlayer(now);drawNpc(now)}else{drawNpc(now);drawPlayer(now)}drawLighting(dt);drawParticles(now);placeOverlays(now)}requestAnimationFrame(tick)}
canvas.addEventListener('pointerdown',e=>{if(!ready||modal.open)return;canvas.focus({preventScroll:true});const r=canvas.getBoundingClientRect(),x=camera.x+(e.clientX-r.left)/r.width*camera.w,y=camera.y+(e.clientY-r.top)/r.height*camera.h;const o=objects().find(o=>inRect(x,y,o.hit));if(o)requestAction(o.id);else goTo(x,y)});
const keyMap={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'};document.addEventListener('keydown',e=>{if(modal.open)return;const k=keyMap[e.key]||keyMap[e.key.toLowerCase()];if(k){e.preventDefault();keys.add(k)}if(e.key.toLowerCase()==='e'&&!e.repeat){let list=objects().filter(o=>Math.hypot(player.x-o.target[0],player.y-o.target[1])<190);list.sort((a,b)=>Math.hypot(player.x-a.target[0],player.y-a.target[1])-Math.hypot(player.x-b.target[0],player.y-b.target[1]));if(list[0])requestAction(list[0].id);else toast('靠近物品，或点击它上面的小图标。')}if(e.key==='Escape')standUp()});document.addEventListener('keyup',e=>keys.delete(keyMap[e.key]||keyMap[e.key.toLowerCase()]));window.addEventListener('blur',()=>keys.clear());document.querySelectorAll('[data-dir]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.dir)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(b.dataset.dir)});
let audio,audioGain,soundOn=false,melodyTimer,noiseNode;function updateAudio(){if(audioGain&&audio)audioGain.gain.setTargetAtTime(scene==='beach'?.055:.018,audio.currentTime,.6)}
async function toggleAudio(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();audioGain=audio.createGain();audioGain.gain.value=0;audioGain.connect(audio.destination);const buf=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate),data=buf.getChannelData(0);let v=0;for(let i=0;i<data.length;i++){v=(v+Math.random()*.04-.02)*.985;data[i]=v*4}noiseNode=audio.createBufferSource();noiseNode.buffer=buf;noiseNode.loop=true;const filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=500;noiseNode.connect(filter);filter.connect(audioGain);noiseNode.start()}soundOn=!soundOn;if(soundOn){await audio.resume();updateAudio();melodyTimer=setInterval(()=>{if(scene!=='home'||document.hidden)return;const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=[261.63,329.63,392,523.25][Math.floor(Math.random()*4)];gain.gain.setValueAtTime(0,audio.currentTime);gain.gain.linearRampToValueAtTime(.014,audio.currentTime+.2);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+3);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+3.1)},4500)}else{audioGain.gain.setTargetAtTime(0,audio.currentTime,.3);clearInterval(melodyTimer)}$('#sound').classList.toggle('active',soundOn);$('#sound').setAttribute('aria-pressed',String(soundOn));$('#sound').setAttribute('aria-label',soundOn?'关闭环境音':'打开环境音');$('#sound').title=soundOn?'关闭环境音':'打开环境音';toast(soundOn?'环境音已打开，轻一点，慢一点。':'环境音已关闭。')}catch{toast('当前浏览器暂时无法播放环境音。')}}$('#sound').onclick=toggleAudio;document.addEventListener('visibilitychange',()=>{keys.clear();if(audio&&soundOn){if(document.hidden)audio.suspend();else audio.resume()}if(!document.hidden)updateClock()});
async function init(){try{await Promise.all([loadImage('home','home.webp'),loadImage('girlWalk','girlWalk.png'),loadImage('girlActions','girlActions.png'),loadImage('boy','boy.png'),...['spring','summer','autumn','winter'].flatMap(s=>['day','night'].map(p=>loadImage(s+'-'+p,s+'-'+p+'.webp')))]);makeSprites();rebuildGrid();updateClock();nightAmount=phase==='night'?1:0;renderActions();ready=true;resize();$('#loading').hidden=true;setTimeout(()=>say('生日快乐，嘟嘟！点点我，收一份祝福吧。',{x:npc.x,y:npc.y-145}),800)}catch(e){$('#loading').innerHTML='<strong>小屋还没准备好</strong><small>有一张素材暂时没能送达，请再试一次。</small><button class="primary-btn" id="retry-load">重新打开小屋</button>';$('#retry-load').onclick=()=>location.reload();console.error(e)}}
updateClock();setInterval(updateClock,1000);requestAnimationFrame(tick);init();
